from collections import deque


class Book:
    def __init__(self, copies):
        self.free = copies
        self.holders = set()
        self.queue = deque()


class Library:
    def __init__(self):
        self.books = {}
        self.faculty = set()

    def add(self, book, copies):
        self.books[book] = Book(copies)
        return f"{book}: {copies} copies"

    def borrow(self, book, member):
        b = self.books.get(book)
        if b is None:
            return f"error: no book {book}"
        if member in b.holders or member in b.queue:
            return f"error: {member} already has or awaits {book}"
        # TODO: take a free copy, or join the queue and report the position.
        return f"{member} borrows {book}"

    def _enqueue(self, b, member):
        b.queue.append(member)

    def give_back(self, book, member):
        b = self.books.get(book)
        if b is None or member not in b.holders:
            return f"error: {member} does not have {book}"
        # TODO: the copy goes to the first person waiting, if anyone is; otherwise it becomes free.
        return f"{member} returns {book}"

    def waiting(self, book):
        b = self.books.get(book)
        if b is None:
            return f"error: no book {book}"
        return f"{book}: " + (", ".join(b.queue) if b.queue else "nobody waiting")

import sys

from library import Library


def main():
    lib = Library()
    for raw in sys.stdin:
        p = raw.split()
        if not p:
            continue
        if p[0] == "COPIES" and len(p) == 3 and p[2].isdigit() and int(p[2]) > 0:
            print(lib.add(p[1], int(p[2])))
        elif p[0] == "BORROW" and len(p) == 3:
            print(lib.borrow(p[1], p[2]))
        elif p[0] == "RETURN" and len(p) == 3:
            print(lib.give_back(p[1], p[2]))
        elif p[0] == "QUEUE" and len(p) == 2:
            print(lib.waiting(p[1]))
        else:
            print(f"error: bad command {raw.strip()}")


main()

