import java.util.*;

class Book {
    int free;
    final Set<String> holders = new HashSet<>();
    final LinkedList<String> queue = new LinkedList<>();

    Book(int copies) { free = copies; }
}

class Library {
    final Map<String, Book> books = new HashMap<>();
    final Set<String> faculty = new HashSet<>();

    String add(String book, int copies) {
        books.put(book, new Book(copies));
        return book + ": " + copies + " copies";
    }

    String borrow(String book, String member) {
        Book b = books.get(book);
        if (b == null) return "error: no book " + book;
        if (b.holders.contains(member) || b.queue.contains(member)) return "error: " + member + " already has or awaits " + book;
        // TODO: take a free copy, or join the queue and report the position.
        return member + " borrows " + book;
    }

    void enqueue(Book b, String member) {
        b.queue.addLast(member);
    }

    String giveBack(String book, String member) {
        Book b = books.get(book);
        if (b == null || !b.holders.contains(member)) return "error: " + member + " does not have " + book;
        // TODO: the copy goes to the first person waiting, if anyone is; otherwise it becomes free.
        return member + " returns " + book;
    }

    String waiting(String book) {
        Book b = books.get(book);
        if (b == null) return "error: no book " + book;
        return book + ": " + (b.queue.isEmpty() ? "nobody waiting" : String.join(", ", b.queue));
    }
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();
        Library lib = new Library();
        for (String raw; (raw = in.readLine()) != null; ) {
            String[] p = raw.trim().split("\\s+");
            if (p[0].isEmpty()) continue;
            String reply;
            if (p[0].equals("COPIES") && p.length == 3 && p[2].matches("\\d+") && Integer.parseInt(p[2]) > 0) reply = lib.add(p[1], Integer.parseInt(p[2]));
            else if (p[0].equals("BORROW") && p.length == 3) reply = lib.borrow(p[1], p[2]);
            else if (p[0].equals("RETURN") && p.length == 3) reply = lib.giveBack(p[1], p[2]);
            else if (p[0].equals("QUEUE") && p.length == 2) reply = lib.waiting(p[1]);
            else reply = "error: bad command " + raw.trim();
            out.append(reply).append('\n');
        }
        System.out.print(out);
    }
}

