    String borrow(String book, String member) {
        Book b = books.get(book);
        if (b == null) return "error: no book " + book;
        if (b.holders.contains(member) || b.queue.contains(member)) return "error: " + member + " already has or awaits " + book;
        if (b.free > 0) {
            b.free--;
            b.holders.add(member);
            return member + " borrows " + book;
        }
        enqueue(b, member);
        return member + " waits for " + book + " (position " + (b.queue.indexOf(member) + 1) + ")";
    }

    void enqueue(Book b, String member) {
        b.queue.addLast(member);
