        if (b == null || !b.holders.contains(member)) return "error: " + member + " does not have " + book;
        b.holders.remove(member);
        if (!b.queue.isEmpty()) {
            String next = b.queue.removeFirst();
            b.holders.add(next);
            return member + " returns " + book + ", now with " + next;
        }
        b.free++;
        return member + " returns " + book;
    }

    String waiting(String book) {
        Book b = books.get(book);
        if (b == null) return "error: no book " + book;
        return book + ": " + (b.queue.isEmpty() ? "nobody waiting" : String.join(", ", b.queue));
    }
}

